#!/usr/bin/env bash
# Publish every server-*.json manifest that the official MCP Registry does not
# yet have at that version. Manifests are generated by `node scripts/sync-areas.js`
# from each area module's `server.description`; do not hand-edit them.
#
# Usage:
#   mcp-publisher login github          # once per machine, interactive (Chris's GitHub)
#   scripts/publish-registry.sh         # publishes what is missing
#   scripts/publish-registry.sh --check # only reports, publishes nothing
#
# Registry names are io.github.physics-star-cat/<name>; names and URLs are forever.
set -euo pipefail
cd "$(dirname "$0")/.."
REG="https://registry.modelcontextprotocol.io/v0/servers"
CHECK="${1:-}"
missing=0
for f in server-*.json; do
  name=$(python3 -c "import json;print(json.load(open('$f'))['name'])")
  ver=$(python3 -c "import json;print(json.load(open('$f'))['version'])")
  # The registry search API is slow and sometimes times out; retry, and treat a
  # failed lookup as "unknown" rather than aborting the whole run.
  body=""
  for attempt in 1 2 3; do
    body=$(curl -s -m 60 "$REG?search=$name&limit=10" || true)
    [[ -n "$body" ]] && break
    sleep 5
  done
  live=$(printf '%s' "$body" | python3 -c "
import sys,json
try:
  d=json.load(sys.stdin)
  print(','.join(sorted({(s.get('server') or s)['version'] for s in d.get('servers',[]) if (s.get('server') or s)['name']=='$name'})))
except Exception: print('?')")
  if [[ ",$live," == *",$ver,"* ]]; then
    echo "ok        $name $ver"
    continue
  fi
  if [[ "$live" == "?" || -z "$body" ]]; then
    echo "UNKNOWN   $name $ver (registry lookup failed; re-run)"
    continue
  fi
  # The registry's search index lags publishes by minutes: re-ask before
  # calling something missing (and before trying to publish it twice).
  for retry in 1 2; do
    sleep 10
    again=$(curl -s -m 60 "$REG?search=$name&limit=10" | python3 -c "
import sys,json
try:
  d=json.load(sys.stdin); print(','.join(sorted({(s.get('server') or s)['version'] for s in d.get('servers',[]) if (s.get('server') or s)['name']=='$name'})))
except Exception: print('')")
    [[ ",$again," == *",$ver,"* ]] && break
  done
  if [[ ",$again," == *",$ver,"* ]]; then
    echo "ok        $name $ver (after index catch-up)"
    continue
  fi
  missing=$((missing+1))
  if [[ "$CHECK" == "--check" ]]; then
    echo "MISSING   $name $ver (registry has: ${live:-none})"
    continue
  fi
  echo "publishing $name $ver (registry has: ${live:-none})"
  mcp-publisher validate "$f"
  mcp-publisher publish "$f"
done
echo "$missing manifest(s) were not on the registry at their current version."
